/**
 * An agent run's steps, each with its status (`design/components/plan.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/plan.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { Icon, MEMBER_PROVIDERS, classes, derived, useMember, type Each } from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/plan.module.css'

export type PlanStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped'

export interface PlanStep {
  id: string
  title: string
  description?: string
  status: PlanStatus
}

export interface PlanMessages {
  status: Record<PlanStatus, string>
}

/** An agent run's steps, each with its status: the inputs it takes, by the React member's prop names. */
export interface PlanProps {
  /**
   * The list's accessible name, such as "Plan for this run" rather than "Plan".
   */
  label: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PlanMessages
  /**
   * The steps in reading order. Plan never sorts them, and an empty list renders nothing.
   */
  steps: PlanStep[]
}

/** An agent run's steps, each with its status. */
@Component({
  selector: 'pm-plan',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `@if (e1()) {<div
[attr.class]="e2()"
data-member="plan"
><!-- list -->
<ol
[attr.class]="e3()"
role="list"
[attr.aria-label]="e4()"
>@for (step of e5(); track e6(step)) {<!-- step -->
<li
[attr.class]="e7()"
[attr.data-status]="e8(step)"
[attr.aria-current]="e9(step)"
[attr.aria-busy]="e10(step)"
><!-- mark -->
<span
[attr.class]="e11()"
aria-hidden="true"
>@if (e12(step)) {<span
[attr.class]="e13(step)"
><pm-icon
name="loading"
size="sm"
></pm-icon></span>} @else if (e14(step)) {<span
[attr.class]="e15(step)"
><pm-icon
name="success"
size="sm"
></pm-icon></span>} @else if (e16(step)) {<span
[attr.class]="e17(step)"
><pm-icon
name="error"
size="sm"
></pm-icon></span>} @else if (e18(step)) {<span
[attr.class]="e19(step)"
><pm-icon
name="remove"
size="sm"
></pm-icon></span>} @else {<span
[attr.class]="e20(step)"
><pm-icon
name="time"
size="sm"
></pm-icon></span>}</span>
<!-- copy -->
<span
[attr.class]="e21()"
><!-- title -->
<span
[attr.class]="e22()"
>{{ e23(step) }}</span>
<span
[attr.class]="e24()"
>{{ e25(step) }}</span>
@if (e26(step)) {<!-- description -->
<span
[attr.class]="e27(step)"
>{{ e28(step) }}</span>}</span></li>}</ol>
<!-- line -->
<p
[attr.class]="e29()"
role="status"
>{{ e30() }}</p></div>}`,
})
export class Plan {
  /**
   * The list's accessible name, such as "Plan for this run" rather than "Plan".
   */
  readonly label = input.required<PlanProps['label']>()
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<Exclude<PlanProps['messages'], undefined>, PlanProps['messages']>(
    (() => ({
      status: {
        pending: 'Pending',
        running: 'Running',
        done: 'Done',
        error: 'Failed',
        skipped: 'Skipped',
      },
    }))(),
    {
      transform: (value: PlanProps['messages']) =>
        value === undefined
          ? (() => ({
              status: {
                pending: 'Pending',
                running: 'Running',
                done: 'Done',
                error: 'Failed',
                skipped: 'Skipped',
              },
            }))()
          : value,
    },
  )
  /**
   * The steps in reading order. Plan never sorts them, and an empty list renders nothing.
   */
  readonly steps = input.required<PlanProps['steps']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      messages: () => this.messages(),
      steps: () => this.steps(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly currentId = derived(
    () => this.$p.steps.find((step) => step.status === 'running')?.id,
  )
  protected readonly announcement = derived(() =>
    ((front: PlanStep | undefined) =>
      front === undefined ? '' : `${front.title}, ${this.$p.messages.status[front.status]}`)(
      this.$p.steps.find((step) => step.status === 'running') ??
        this.$p.steps.find((step) => step.status === 'error') ??
        [...this.$p.steps]
          .reverse()
          .find((step) => step.status === 'done' || step.status === 'skipped'),
    ),
  )

  protected e1() {
    return this.$p.steps.length > 0
  }

  protected e2() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.root
  }

  protected e3() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.list
  }

  protected e4() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return this.$p.label
  }

  e5() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return this.$p.steps
  }

  protected e6(step: Each<ReturnType<Plan['e5']>>) {
    return step.id
  }

  protected e7() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.step
  }

  protected e8(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.status
  }

  protected e9(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.id === this.currentId.value ? 'step' : undefined
  }

  protected e10(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.status === 'running' ? true : undefined
  }

  protected e11() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.mark
  }

  protected e12(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.status === 'running'
  }

  protected e13(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (!(step.status === 'running')) return undefined as never
    return classes(styles.glyph, styles.spinning)
  }

  protected e14(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    return step.status === 'done'
  }

  protected e15(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (!(step.status === 'done')) return undefined as never
    return styles.glyph
  }

  protected e16(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (step.status === 'done') return undefined as never
    return step.status === 'error'
  }

  protected e17(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (step.status === 'done') return undefined as never
    if (!(step.status === 'error')) return undefined as never
    return styles.glyph
  }

  protected e18(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (step.status === 'done') return undefined as never
    if (step.status === 'error') return undefined as never
    return step.status === 'skipped'
  }

  protected e19(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (step.status === 'done') return undefined as never
    if (step.status === 'error') return undefined as never
    if (!(step.status === 'skipped')) return undefined as never
    return styles.glyph
  }

  protected e20(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (step.status === 'running') return undefined as never
    if (step.status === 'done') return undefined as never
    if (step.status === 'error') return undefined as never
    if (step.status === 'skipped') return undefined as never
    return styles.glyph
  }

  protected e21() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.copy
  }

  protected e22() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.title
  }

  protected e23(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.title
  }

  protected e24() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.reader
  }

  protected e25(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return `, ${this.$p.messages.status[step.status]}`
  }

  protected e26(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return step.description !== undefined
  }

  protected e27(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (!(step.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e28(step: Each<ReturnType<Plan['e5']>>) {
    if (!(this.$p.steps.length > 0)) return undefined as never
    if (!(step.description !== undefined)) return undefined as never
    return step.description
  }

  protected e29() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return styles.line
  }

  protected e30() {
    if (!(this.$p.steps.length > 0)) return undefined as never
    return this.announcement.value
  }
}
